<template>
  <div class="app-container">
    <el-alert title="联盟账号由 sys_union_platform 管理。密钥和访问令牌不回显；编辑时留空表示保留原值。唯品会、抖音目前无对应后端平台实现，仅显示未接入，不提供模拟配置。" type="info" :closable="false" />
    <el-tabs v-model="tab" @tab-click="load">
      <el-tab-pane label="联盟账号" name="accounts">
        <el-form :inline="true" size="small" label-width="82px"><el-form-item label="平台"><el-select v-model="filter.platformType" clearable><el-option v-for="p in supported" :key="p.value" :label="p.label" :value="p.value"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="filter.isQuote" clearable><el-option label="未使用" value="0"/><el-option label="使用中" value="1"/><el-option label="失效" value="2"/></el-select></el-form-item><el-form-item><el-button type="primary" size="mini" @click="load">搜索</el-button><el-button size="mini" @click="filter={platformType:'',isQuote:''};load()">重置</el-button></el-form-item></el-form>
        <el-row class="mb8"><el-button type="primary" plain size="mini" icon="el-icon-plus" @click="add" v-hasPermi="['system:unionPlatform:add']">新增账号</el-button><el-button size="mini" plain @click="status('1')" :disabled="!selected" v-hasPermi="['system:unionPlatform:edit']">设为使用中</el-button><el-button size="mini" plain @click="status('0')" :disabled="!selected" v-hasPermi="['system:unionPlatform:edit']">设为未使用</el-button><el-button size="mini" plain @click="status('2')" :disabled="!selected" v-hasPermi="['system:unionPlatform:edit']">标记失效</el-button></el-row>
        <el-table v-loading="loading" :data="rows" @selection-change="v=>selected=v[0]||null"><el-table-column type="selection" width="48"/><el-table-column label="平台" prop="platformType" width="110"><template slot-scope="s">{{platformLabel(s.row.platformType)}}</template></el-table-column><el-table-column label="账号名称" prop="platformName" min-width="140" show-overflow-tooltip/><el-table-column label="密钥" width="115"><template slot-scope="s"><el-tag type="info">{{s.row.hasAppSecret?'已设置':'未设置'}}</el-tag></template></el-table-column><el-table-column label="令牌" width="100"><template slot-scope="s"><el-tag type="info">{{s.row.hasAccessToken?'已设置':'未设置'}}</el-tag></template></el-table-column><el-table-column label="站点 ID" prop="siteId" width="120"/><el-table-column label="推广位 ID" prop="adzoneId" width="140"/><el-table-column label="使用状态" width="105"><template slot-scope="s"><el-tag :type="s.row.isQuote==='1'?'success':s.row.isQuote==='2'?'danger':'info'">{{statusLabel(s.row.isQuote)}}</el-tag></template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template slot-scope="s"><el-button type="text" size="mini" @click="edit(s.row)" v-hasPermi="['system:unionPlatform:edit']">修改</el-button></template></el-table-column></el-table>
        <pagination v-show="total>0" :total="total" :page.sync="pageNum" :limit.sync="pageSize" @pagination="load" />
      </el-tab-pane>
      <el-tab-pane label="PID 池" name="pid">
        <el-form :inline="true" size="small" label-width="80px"><el-form-item label="平台"><el-select v-model="pidPlatform" @change="loadPids"><el-option v-for="p in platforms" :key="p.value" :label="p.label" :value="p.value.toUpperCase()"/></el-select></el-form-item><el-form-item><el-button type="primary" size="mini" @click="loadPids">刷新</el-button><el-button size="mini" type="primary" plain @click="pidOpen=true;pidForm={pid:'',type:'TRACKING',enabled:true,reason:''}" v-hasPermi="['system:commission:pid:edit']">登记 PID</el-button></el-form-item></el-form>
        <el-table v-loading="pidLoading" :data="pids"><el-table-column label="平台" prop="platform" width="120"/><el-table-column label="PID" prop="pid" min-width="240"/><el-table-column label="类型" prop="type" width="150"><template slot-scope="s"><el-tag>{{pidTypeLabel(s.row.type)}}</el-tag></template></el-table-column><el-table-column label="状态" width="110"><template slot-scope="s"><el-tag :type="s.row.enabled?'success':'info'">{{s.row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="180"><template slot-scope="s"><el-button type="text" size="mini" @click="togglePid(s.row)" v-hasPermi="['system:commission:pid:edit']">{{s.row.enabled?'停用':'启用'}}</el-button><el-button type="text" size="mini" @click="changePidType(s.row)" v-hasPermi="['system:commission:pid:edit']">编辑类型</el-button></template></el-table-column></el-table>
        <el-divider/><el-alert title="单品占用统计接口仅返回指定商品的聚合结果，暂不支持商品列表、占用率排序和租约配置。可按商品 ID 查询占用统计。" type="warning" :closable="false"/><el-form :inline="true" size="small" style="margin-top:12px"><el-form-item label="商品 ID"><el-input v-model="itemId" clearable/></el-form-item><el-form-item><el-button @click="loadOccupancy" type="primary" size="mini">查询占用</el-button></el-form-item></el-form><el-descriptions v-if="occupancy" :column="3" border><el-descriptions-item v-for="(v,k) in occupancy" :key="k" :label="k">{{v}}</el-descriptions-item></el-descriptions>
      </el-tab-pane>
      <el-tab-pane label="唯品会 / 抖音" name="unsupported"><el-empty description="暂无对应平台的后端实体、授权接口和平台适配器，当前未接入。" /></el-tab-pane>
    </el-tabs>
    <el-dialog :title="form.id?'编辑联盟账号':'新增联盟账号'" :visible.sync="open" width="650px" append-to-body><el-form :model="form" :rules="rules" ref="unionForm" label-width="140px"><el-form-item label="平台" prop="platformType"><el-select v-model="form.platformType"><el-option v-for="p in supported" :key="p.value" :value="p.value" :label="p.label"/></el-select></el-form-item><el-form-item label="账号名称" prop="platformName"><el-input v-model="form.platformName"/></el-form-item><el-form-item label="App Key" prop="appKey"><el-input v-model="form.appKey" :readonly="!!form.id" :placeholder="form.id?'App Key 不回显':'请输入 App Key'"/></el-form-item><el-form-item label="App Secret"><el-input v-model="form.appSecret" type="password" show-password autocomplete="new-password" :placeholder="form.id?'已设置时留空保持不变':'输入后仅提交，不会回显'"/></el-form-item><el-form-item label="访问令牌"><el-input v-model="form.accessToken" type="password" show-password autocomplete="new-password" :placeholder="form.id?'已设置时留空保持不变':'输入后仅提交，不会回显'"/></el-form-item><el-form-item label="站点 ID"><el-input v-model="form.siteId"/></el-form-item><el-form-item label="推广位 ID"><el-input v-model="form.adzoneId"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea"/></el-form-item></el-form><div slot="footer"><el-button type="primary" :loading="saving" @click="saveUnion">保存</el-button><el-button @click="open=false">取消</el-button></div></el-dialog>
    <el-dialog title="登记 PID" :visible.sync="pidOpen" width="520px" append-to-body><el-form :model="pidForm" label-width="120px"><el-form-item label="PID"><el-input v-model="pidForm.pid"/></el-form-item><el-form-item label="类型"><el-select v-model="pidForm.type"><el-option v-for="x in pidTypes" :key="x.value" :value="x.value" :label="x.label"/></el-select></el-form-item><el-form-item label="启用"><el-switch v-model="pidForm.enabled"/></el-form-item><el-form-item label="原因 / 备注"><el-input v-model="pidForm.reason" type="textarea"/></el-form-item></el-form><div slot="footer"><el-button type="primary" :loading="saving" @click="savePidForm">保存</el-button><el-button @click="pidOpen=false">取消</el-button></div></el-dialog>
  </div>
</template>
<script>
import { unionRows,getUnion,addUnion,editUnion,setUnionStatus,pidRows,savePid,cpsDict } from '@/api/cps/settings'
import { pidOccupancy } from '@/api/cps/attribution'
export default {name:'CpsUnion',data(){return{tab:'accounts',loading:false,saving:false,rows:[],total:0,pageNum:1,pageSize:10,filter:{platformType:'',isQuote:''},selected:null,open:false,form:{},rules:{platformType:[{required:true,message:'请选择平台',trigger:'change'}],platformName:[{required:true,message:'请输入账号名称',trigger:'blur'}],appKey:[{required:true,message:'请输入 App Key',trigger:'blur'}]},platforms:[],supported:[],pidPlatform:'TBK',pidLoading:false,pids:[],pidOpen:false,pidForm:{},pidTypes:[{value:'TRACKING',label:'追踪'},{value:'DEFAULT',label:'默认'},{value:'BLOCKED',label:'屏蔽'},{value:'REDPACKET',label:'红包'}],itemId:'',occupancy:null}},created(){cpsDict().then(r=>{this.platforms=(r.data&&r.data.platforms)||[];this.supported=this.platforms.filter(x=>['tbk','jd','pdd'].includes(x.value))});this.tab=this.$route.query.tab==='pid'?'pid':'accounts';if(this.tab==='pid')this.loadPids();else this.load()},methods:{load(){if(this.tab!=='accounts')return;this.loading=true;unionRows({...this.filter,pageNum:this.pageNum,pageSize:this.pageSize}).then(r=>{this.rows=r.rows||[];this.total=r.total||0}).finally(()=>{this.loading=false})},loadPids(){this.pidLoading=true;pidRows(this.pidPlatform.toLowerCase()).then(r=>{this.pids=r.data||[]}).finally(()=>{this.pidLoading=false})},add(){this.form={platformType:this.filter.platformType||'',platformName:'',appKey:'',appSecret:'',accessToken:'',siteId:'',adzoneId:'',remark:''};this.open=true},edit(row){getUnion(row.id).then(r=>{const d=r.data||{};this.form={id:d.id,platformType:d.platformType,platformName:d.platformName,appKey:d.appKey,appSecret:'',accessToken:'',siteId:d.siteId,adzoneId:d.adzoneId,remark:d.remark,hasAppSecret:d.hasAppSecret,hasAccessToken:d.hasAccessToken};this.open=true})},saveUnion(){this.$refs.unionForm.validate(ok=>{if(!ok)return;this.saving=true;const d={...this.form};delete d.hasAppSecret;delete d.hasAccessToken;const req=d.id?editUnion(d):addUnion(d);req.then(()=>{this.$modal.msgSuccess('联盟账号保存成功');this.open=false;this.load()}).finally(()=>{this.saving=false})})},status(v){if(!this.selected)return;this.$modal.confirm(`确认将 ${this.platformLabel(this.selected.platformType)} / ${this.selected.platformName} 状态设为${this.statusLabel(v)}？`).then(()=>setUnionStatus({id:this.selected.id,isQuote:v})).then(()=>{this.$modal.msgSuccess('状态修改成功');this.load()}).catch(()=>{})},platformLabel(v){const x=this.platforms.find(p=>p.value===v);return x?x.label:v},statusLabel(v){return {'0':'未使用','1':'使用中','2':'失效'}[v]||v},pidTypeLabel(v){return {TRACKING:'追踪',DEFAULT:'默认',BLOCKED:'屏蔽',REDPACKET:'红包'}[v]||v},savePidForm(){if(!this.pidForm.pid||!this.pidForm.reason){this.$modal.msgError('PID 和原因/备注必填');return}this.saving=true;savePid({...this.pidForm,platform:this.pidPlatform.toUpperCase()}).then(()=>{this.$modal.msgSuccess('PID 保存成功');this.pidOpen=false;this.loadPids()}).finally(()=>{this.saving=false})},togglePid(row){this.$modal.confirm(`确认${row.enabled?'停用':'启用'} PID ${row.pid}？`).then(()=>savePid({...row,enabled:!row.enabled,reason:row.reason||'后台状态调整'})).then(()=>this.loadPids()).catch(()=>{})},changePidType(row){this.$prompt('请选择 PID 类型：TRACKING / DEFAULT / BLOCKED / REDPACKET；填写类型名称。','编辑 PID 类型',{inputValue:row.type}).then(({value})=>{if(!this.pidTypes.some(x=>x.value===value)){this.$modal.msgError('类型值无效');return}if(value==='BLOCKED')return this.$modal.confirm('该 PID 下订单将不可人工认领，确认？').then(()=>savePid({...row,type:value,reason:'后台修改类型'}));return savePid({...row,type:value,reason:'后台修改类型'})}).then(()=>this.loadPids()).catch(()=>{})},loadOccupancy(){if(!this.itemId){this.$modal.msgError('请填写商品 ID');return}pidOccupancy(this.pidPlatform.toUpperCase(),this.itemId).then(r=>{this.occupancy=r.data})}}}
</script>
